mapper.update:
UPDATE entry
SET deleted_at = NULL, updated_at = now()
WHERE id = #{id}

mapper.select:
SELECT 
FROM entry
WHERE deleted_at IS NULL

    AND type = #{type}


    AND source_date <= #{date}


    AND (source_date < #{cursorDate}
         OR (source_date = #{cursorDate} AND id < #{cursorId}))

ORDER BY source_date DESC, id DESC
LIMIT #{limit}

SELECT FROM entry WHERE deleted_at IS NULL AND (content_plain ILIKE #{pattern} OR title ILIKE #{pattern})
AND type = #{type}
ORDER BY (title ILIKE #{pattern}) DESC, pinned DESC, source_date DESC, id DESC LIMIT #{limit}
